# Bandwidth safeguard only (not needed for correct scaling -- see module
# docstring): a source image larger than this on either side is
# downsampled before transmission, nothing more.
_MAX_TRANSMIT_SIDE = 2000

# Best-effort unique-enough image ids: random start, incrementing, entirely
# client-side. We can't read the terminal's own id-allocation responses
# back to confirm -- Textual owns stdin with its own reader thread, so
# nothing in this process can safely read a terminal response once the app
# has started (see the module docstring on why this can't just ask the
# terminal to pick one for us).
_image_id_counter = count(randint(1, 2**31))

_IS_TMUX = bool(os.environ.get("TMUX"))


def _write(sequence: str) -> None:
    stdout = sys.__stdout__
    if stdout is None or not stdout.isatty():
        return
    if _IS_TMUX:
        # tmux passthrough DCS envelope: wrap the whole sequence, and
        # double any ESC bytes inside it (tmux's own passthrough syntax).
        sequence = "\x1bPtmux;" + sequence.replace("\x1b", "\x1b\x1b") + "\x1b\\"
    stdout.write(sequence)
    stdout.flush()


def _send(payload: str | None = None, **control: int | str | None) -> None:
    fields = ",".join(f"{k}={v}" for k, v in control.items() if v is not None)
    _write(f"{_TGP_START}{fields}{';' + payload if payload else ''}{_TGP_END}")


def _transmit(image: PILImage.Image, image_id: int) -> None:
    if image.width > _MAX_TRANSMIT_SIDE or image.height > _MAX_TRANSMIT_SIDE:
        image = image.copy()
        image.thumbnail((_MAX_TRANSMIT_SIDE, _MAX_TRANSMIT_SIDE), PILImage.Resampling.LANCZOS)

    buf = io.BytesIO()
    image.convert("RGBA").save(buf, format="PNG", compress_level=2)
    data = b64encode(buf.getvalue()).decode("ascii")

    while data:
        chunk, data = data[:_CHUNK_SIZE], data[_CHUNK_SIZE:]
        # f=100: PNG payload (Kitty decodes it itself, no raw-pixel-format
        # bookkeeping on our side). q=2: suppress every response -- we
        # have no safe way to read one back once Textual owns stdin.
        _send(payload=chunk, i=image_id, m=1 if data else 0, f=100, q=2)


def _place(image_id: int, columns: int, rows: int) -> None:
    # p=1: a fixed placement id, not left to the terminal to pick one. Some
    # terminals -- Ghostty included, per a real reported case -- only
    # replace the image *data* on a re-transmit of the same image id and
    # leave a previous unnamed placement dangling rather than replacing it
    # too; naming it explicitly sidesteps that rather than depending on it.
    _send(a="p", i=image_id, p=1, c=columns, r=rows, U=1, q=2)


def _delete(image_id: int) -> None:
    _send(a="d", i=image_id, p=1, q=2)


def _fit_cells(image_width: int, image_height: int, max_cols: int, max_rows: int) -> tuple[int, int]:
    """Largest (cols, rows) within (max_cols, max_rows) that keeps the
    image's own aspect ratio, given a typical monospace cell's pixel
    proportions (roughly twice as tall as wide -- close enough for this
    without querying the terminal's actual cell pixel size, which would
    need the same raw-stdin access this module otherwise avoids)."""
    if max_cols <= 0 or max_rows <= 0 or image_width <= 0 or image_height <= 0:
        return 0, 0

    cell_aspect = 0.5  # assumed cell width / cell height
    rows_for_full_width = max(1, round(max_cols * cell_aspect * image_height / image_width))
    if rows_for_full_width <= max_rows:
        return max_cols, rows_for_full_width

    cols_for_full_height = max(1, round(max_rows * image_width / (cell_aspect * image_height)))
    return min(cols_for_full_height, max_cols), max_rows


class KittyImage(Widget):
    """Displays a PIL image (or a path to one) via Kitty's Terminal
    Graphics Protocol. Renders nothing on a terminal that doesn't speak
    that protocol -- see the module docstring for why this deliberately
    doesn't fall back to Sixel/halfblocks/etc.

    Deliberately no ``content-align``/padding CSS: the placeholder
    technique this renders with (see module docstring) depends on each
    placeholder character landing at an *exact* cell offset from the
    placement's own top-left -- anything that pads or re-centers the
    rendered text within the widget's box would shift those offsets
    relative to what the row/column diacritics actually encode.
    """

    def __init__(
        self,
        image: str | Path | IO[bytes] | PILImage.Image,
        *,
        on_error: Callable[[Exception], Widget] | None = None,
        name: str | None = None,
        id: str | None = None,  # noqa: A002 -- matches Widget's own param name
        classes: str | None = None,
        disabled: bool = False,
    ) -> None:
        super().__init__(name=name, id=id, classes=classes, disabled=disabled)
        self._image: PILImage.Image | None = None
        self._error_widget: Widget | None = None
        self._image_id: int | None = None
        self._placed_size: tuple[int, int] | None = None
        self._cached_render: Text | None = None

        try:
            self._image = image if isinstance(image, PILImage.Image) else PILImage.open(image)
        except Exception as exc:  # noqa: BLE001 -- reported via on_error, not swallowed
            if on_error is None:
                raise
            self._error_widget = on_error(exc)

    def compose(self):
        if self._error_widget is not None:
            yield self._error_widget

    def on_unmount(self) -> None:
        if self._image_id is not None:
            _delete(self._image_id)
            self._image_id = None

    def render(self) -> Text | str:
        if self._image is None:
            return ""

        size = self.size
        if size.width <= 0 or size.height <= 0:
            return ""

        if self._image_id is None:
            self._image_id = next(_image_id_counter)
            _transmit(self._image, self._image_id)

        if self._cached_render is None or self._placed_size != (size.width, size.height):
            self._placed_size = (size.width, size.height)
            cols, rows = _fit_cells(self._image.width, self._image.height, size.width, size.height)
            _place(self._image_id, cols, rows)
            self._cached_render = _build_placeholder_text(self._image_id, cols, rows)

        return self._cached_render


def _build_placeholder_text(image_id: int, cols: int, rows: int) -> Text:
    style = Style(color=f"rgb({(image_id >> 16) & 255},{(image_id >> 8) & 255},{image_id & 255})")
    id_diacritic = chr(_NUMBER_TO_DIACRITIC[(image_id >> 24) & 255])
    lines = [
        "".join(f"{_PLACEHOLDER}{chr(_NUMBER_TO_DIACRITIC[r])}{chr(_NUMBER_TO_DIACRITIC[c])}{id_diacritic}" for c in range(cols))
        for r in range(rows)
    ]
    return Text("\n".join(lines), style=style, no_wrap=True)
